from typing import Optional, List, Dict, Any

from taf.ul.sbts.energy_saving.decorators.connection import with_connection
from taf.ul.sbts.energy_saving.core.context import EnergySavingContext
from taf.ul.sbts.energy_saving.workflows.energy_saving_workflow import EnergySetupWorkflow


class energy_saving:
    """High-level interface for energy saving operations.

    Optionally provide a default connection alias at construction time. If not provided,
    pass `connection="alias"` per method call.
    """

    def __init__(self, default_alias: Optional[str] = None):
        self.context = EnergySavingContext(default_alias)
        self._wf = EnergySetupWorkflow(self.context)

    def set_default_connection(self, alias: str):
        """Set or change the default connection alias used by this interface."""
        self.context.set_default_connection(alias)

    @with_connection
    def backup_and_load_scf(self, timeout: int = 300, connection: Optional[str] = None):
        """Backup SCF from the node and return the parsed XML.

        Args:
            timeout: Max time in seconds to wait for the backup.
            connection: Optional connection alias to use for this call.

        Returns:
            Parsed SCF XML object.
        """
        scf_path = self.context.scf_manager.backup_scf(timeout=timeout, connection=connection)
        return self.context.scf_manager.load_scf_xml(scf_path)

    @with_connection
    def enable_5g_energy_saving(self, xml_scf, force_recreate_groups=False,
                                filter_cell_list: Optional[List[Dict[str, Any]]] = None,
                                connection: Optional[str] = None):
        return self._wf.try_to_enable_5g_energy_saving(
            xml_scf, force_recreate_groups, filter_cell_list, connection=connection
        )

    @with_connection
    def enable_4g_energy_saving(self, xml_scf, force_recreate_groups: bool = False,
                                filter_cell_list: Optional[List[Dict[str, Any]]] = None,
                                connection: Optional[str] = None):
        """Enable 4G (LTE) energy saving with optional group recreation and cell filtering."""
        return self._wf.try_to_enable_4g_energy_saving(
            xml_scf, force_recreate_groups, filter_cell_list, connection=connection
        )

    @with_connection
    def setup_complete_energy_saving(
            self,
            xml_scf,
            include_4g: bool = True,
            include_5g: bool = True,
            force_recreate_groups: bool = False,
            cell_nr_filter_params: Optional[Dict] = None,
            cell_lte_filter_params:  Optional[Dict] = None,
            connection: Optional[str] = None,
    ):
        """Enable complete energy saving (4G/5G) and coordination when possible."""
        return self._wf.setup_complete_energy_saving(
            xml_scf,
            include_4g=include_4g,
            include_5g=include_5g,
            force_recreate_groups=force_recreate_groups,
            cell_nr_filter_params=cell_nr_filter_params,
            cell_lte_filter_params=cell_lte_filter_params,
            connection=connection,
        )

    @with_connection
    def disable_energy_saving(self, power_group_dns: List[str], connection: Optional[str] = None):
        """Disable energy saving for provided power group DNs."""
        return self._wf.disable_energy_saving(power_group_dns, connection=connection)

    @with_connection
    def enable_energy_saving(self, power_group_dns: List[str], xml_scf=None, connection: Optional[str] = None):
        """Enable energy saving for provided power group DNs."""
        return self._wf.enable_energy_saving(power_group_dns, xml_scf=xml_scf, connection=connection)

    def get_allowed_missing_cells_count(self, cell_type: str, xml_scf, power_group_dns) -> int:
        """Get allowed missing cells count for given cell type ("NR" or "LTE")."""
        return self._wf.get_allowed_missing_cells_count(cell_type, xml_scf, power_group_dns)

    def get_cell_ids_from_lbpsCellList(self, cell_type: str, xml_scf, group_dn: str) -> List[int]:
        """Get cell IDs from lbpsCellList of a power group for given cell type ("NR" or "LTE")."""
        power_group_manager = self.context.nrpgrp_manager if cell_type.lower() == "nr" else self.context.psgrp_manager
        return power_group_manager.get_cell_ids_from_lbpsCellList(xml_scf, group_dn)

    def get_cells_ids_with_cells_order_from_lbpsCellList(
            self, cell_type: str, xml_scf, group_dn: str) -> Dict[int, int]:
        """Get cell IDs with their lbpsCellSOOrder from lbpsCellList of a power group for given cell type
        ("NR" or "LTE")."""
        power_group_manager = self.context.nrpgrp_manager if cell_type.lower() == "nr" else self.context.psgrp_manager
        return power_group_manager.get_cell_ids_with_cells_order_from_lbpsCellList(xml_scf, group_dn)

    @with_connection
    def wait_until_any_cell_in_energy_saving(
            self,
            cell_type: str,
            timeout: int = 300,
            check_interval: int = 10,
            connection: Optional[str] = None,
    ) -> bool:
        """Wait until any cell of given type ("NR" or "LTE") enters energy saving."""
        return self._wf.wait_until_any_cell_in_energy_saving(
            cell_type, timeout=timeout, check_interval=check_interval, connection=connection
        )

    @with_connection
    def wait_until_all_cells_in_energy_saving(
            self,
            cell_type: str,
            cell_ids: Optional[List[int]] = None,
            timeout: int = 300,
            check_interval: int = 10,
            allowed_missing: int = 0,
            connection: Optional[str] = None,
    ) -> bool:
        """Wait until all cells (or provided subset) of given type enter energy saving."""
        return self._wf.wait_until_all_cells_in_energy_saving(
            cell_type, cell_ids=cell_ids, timeout=timeout, check_interval=check_interval,
            allowed_missing=allowed_missing, connection=connection
        )

    @with_connection
    def check_if_any_cell_in_energy_saving(
            self, cell_type: str, timeout: int = 60, connection: Optional[str] = None
    ) -> bool:
        """Check if any cell of given type is currently in energy saving."""
        return self._wf.check_if_any_cell_in_energy_saving(
            cell_type, timeout=timeout, connection=connection
        )

    @with_connection
    def check_if_all_cells_in_energy_saving(
            self,
            cell_type: str,
            cell_ids: Optional[List[int]] = None,
            timeout: int = 60,
            allowed_missing: int = 0,
            connection: Optional[str] = None,
    ) -> bool:
        """Check if all cells (or provided subset) of given type are in energy saving."""
        return self._wf.check_if_all_cells_in_energy_saving(
            cell_type, cell_ids=cell_ids, timeout=timeout, allowed_missing=allowed_missing, connection=connection
        )

    @with_connection
    def restore_scf(
            self,
            scf_file_path: str,
            bts_id: Optional[int] = None,
            timeout: int = 600,
            connection: Optional[str] = None,
    ):
        """Restore SCF file to the node.

        Args:
            scf_file_path: Path to the SCF XML file to commission.
            bts_id: Optional BTS identifier.
            timeout: Commissioning timeout in seconds.
            connection: Optional connection alias for this call.
        """
        return self.context.scf_manager.restore_scf(
            scf_file_path, bts_id=bts_id, timeout=timeout, connection=connection
        )
